INSERT INTO bugs (id, bug_id, title, severity, module, status, discoverer, assignee, created_date, deadline, solution, created_at, updated_at) VALUES (33, 'BUG1786535307222', '看板数据优化', '一般', 'MES功能', '解决关闭', '崔猛', '崔猛', '2026-06-18', '2026-06-19', '因科彩工厂的上班时间更改，看板上的每个小时记录的表也需要更改；开始时间应为8：30；例：8：30--9：30为第一个小时的数据；', '2026-08-12 11:50:31.883000', '2026-08-12 11:50:31.883000');
